head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// 현재 화면에 표시된 순서(위에서 아래)와 고정 Row 2 건의 값을 출력
scwin.btn_checkOrder_onclick = function (e) {
    var objGrid = $p.getComponentById("target1");
    var arrJson = objGrid.getAllVisibleJSON("col1");
    var arrCol1 = [];
    for (var i = 0; i < arrJson.length; i++) {
        arrCol1.push(arrJson[i].col1);
    }
    scwin.setReturnValue("=====현재 표시 순서 (위에서 아래)=====");
    scwin.setReturnValue("col1 표시 순서 : " + arrCol1.join(", "));
    scwin.setReturnValue("고정 Row 2 건 : " + arrCol1[0] + ", " + arrCol1[1]);
};
